CREATE TABLE recurring_plans(id TEXT PRIMARY KEY,name TEXT NOT NULL,category TEXT NOT NULL CHECK(category IN ('rent','subscription','utilities','insurance','membership','other')),amount_cents INTEGER NOT NULL CHECK(amount_cents BETWEEN 1 AND 99999999999),interval_months INTEGER NOT NULL CHECK(interval_months IN (1,3,6,12)),first_due TEXT NOT NULL,end_date TEXT,paused INTEGER NOT NULL CHECK(paused IN (0,1)),active_from TEXT NOT NULL,notes TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT,CHECK(end_date IS NULL OR end_date>=first_due));
CREATE TABLE plan_payments(id TEXT PRIMARY KEY,plan_id TEXT NOT NULL REFERENCES recurring_plans(id),due_date TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN ('paid','skipped')),paid_date TEXT,amount_cents INTEGER CHECK(amount_cents BETWEEN 1 AND 99999999999),notes TEXT NOT NULL,revision INTEGER NOT NULL CHECK(revision>0),created_at TEXT NOT NULL,updated_at TEXT NOT NULL,deleted_at TEXT,CHECK((state='paid')=(paid_date IS NOT NULL AND amount_cents IS NOT NULL)),CHECK(state='paid' OR (paid_date IS NULL AND amount_cents IS NULL)));
CREATE UNIQUE INDEX plan_payments_period ON plan_payments(plan_id,due_date) WHERE deleted_at IS NULL;
PRAGMA user_version=17;
